package com.google.javascript.rhino.jstype;

import com.google.javascript.rhino.ErrorReporter;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.jstype.JSTypeRegistry.ResolveMode;
import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Comparator;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for JSType.getTypesUnderShallowInequality.
 */
public class JSType_getTypesUnderShallowInequality_TriageGen0Test {

    @Test
    public void testUnionTypeSwapsOrder() {
        // Mocking 'this' as a regular type
        JSType thisType = mock(JSType.class);
        when(thisType.isNullType()).thenReturn(false);
        when(thisType.isVoidType()).thenReturn(false);

        // Mocking 'that' as a UnionType
        UnionType unionType = mock(UnionType.class);
        TypePair innerPair = new TypePair(mock(JSType.class), mock(JSType.class));

        // The implementation calls that.getTypesUnderShallowInequality(this)
        when(unionType.getTypesUnderShallowInequality(thisType)).thenReturn(innerPair);

        TypePair result = thisType.getTypesUnderShallowInequality(unionType);

        // The implementation returns new TypePair(p.typeB, p.typeA)
        assertEquals(innerPair.typeB, result.typeA);
        assertEquals(innerPair.typeA, result.typeB);
    }

    @Test
    public void testBothNullTypes() {
        JSType thisType = mock(JSType.class);
        when(thisType.isNullType()).thenReturn(true);
        when(thisType.isVoidType()).thenReturn(false);

        JSType thatType = mock(JSType.class);
        when(thatType.isNullType()).thenReturn(true);
        when(thatType.isVoidType()).thenReturn(false);

        TypePair result = thisType.getTypesUnderShallowInequality(thatType);

        assertNull(result.typeA);
        assertNull(result.typeB);
    }

    @Test
    public void testBothVoidTypes() {
        JSType thisType = mock(JSType.class);
        when(thisType.isNullType()).thenReturn(false);
        when(thisType.isVoidType()).thenReturn(true);

        JSType thatType = mock(JSType.class);
        when(thatType.isNullType()).thenReturn(false);
        when(thatType.isVoidType()).thenReturn(true);

        TypePair result = thisType.getTypesUnderShallowInequality(thatType);

        assertNull(result.typeA);
        assertNull(result.typeB);
    }

    @Test
    public void testMixedNullAndVoid() {
        // One is null, one is void -> should go to else block
        JSType thisType = mock(JSType.class);
        when(thisType.isNullType()).thenReturn(true);
        when(thisType.isVoidType()).thenReturn(false);

        JSType thatType = mock(JSType.class);
        when(thatType.isNullType()).thenReturn(false);
        when(thatType.isVoidType()).thenReturn(true);

        TypePair result = thisType.getTypesUnderShallowInequality(thatType);

        assertEquals(thisType, result.typeA);
        assertEquals(thatType, result.typeB);
    }

    @Test
    public void testDifferentNonSpecialTypes() {
        JSType thisType = mock(JSType.class);
        when(thisType.isNullType()).thenReturn(false);
        when(thisType.isVoidType()).thenReturn(false);

        JSType thatType = mock(JSType.class);
        when(thatType.isNullType()).thenReturn(false);
        when(thatType.isVoidType()).thenReturn(false);

        TypePair result = thisType.getTypesUnderShallowInequality(thatType);

        assertEquals(thisType, result.typeA);
        assertEquals(thatType, result.typeB);
    }

    /**
     * Helper interface/class to allow mocking UnionType if it's a subclass of JSType.
     * In a real environment, UnionType is a concrete class in the same package.
     */
    private interface UnionType extends JSType {
        // This allows the mock to behave like the real UnionType for the 'instanceof' check 
        // if the testing framework/environment supports it, otherwise we rely on 
        // the actual class hierarchy.
    }
}
